#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
int main(void) {
    size_t n = 3;
    if (n > SIZE_MAX / sizeof(int)) return 1;
    int *a = malloc(n * sizeof *a);
    if (a == NULL) return 1;
    for (size_t i = 0; i < n; ++i) a[i] = (int)i + 1;
    printf("%d\n", a[2]);
    free(a);
    return 0;
}

